  const hero = document.querySelector('main > *, body > *');
  // Find hero: the section containing the h1
  const h1 = document.querySelector('h1');
  let hero = h1;
  while (hero && hero.parentElement && hero.parentElement !== document.body) {
    // find the top-level section ancestor
    hero = hero.parentElement;
  }
  return {
    heroTag: hero ? hero.tagName : null,
    heroClass: hero ? hero.className : null,
    parentTag: hero && hero.parentElement ? hero.parentElement.tagName : null,
    bodyChildren: [...document.body.children].map(c => c.tagName + '.' + c.className.split(' ').slice(0,3).join('.'))
  };
}

